func start_load(path: String) -> bool:
	if _is_loading:
		return false
	if !ResourceLoader.exists(path):
		# Simulate a slight delay to allow other things to happen if needed,
		# but spec says fire within 1s. We emit immediately.
		load_failed.emit("File not found")
		return true

	_is_loading = true
	_current_path = path
	_load_scene.call_deferred(path)
	return true

func cancel() -> void:
	if _is_loading:
		_is_loading = false
		_current_path = ""

func is_loading() -> bool:
	return _is_loading

func _load_scene(path: String) -> void:
	if !_is_loading || _current_path != path:
		return

	# Using thread for background loading
	var thread = Thread.new()
	thread.start(_do_load.bind(path))

func _do_load(path: String) -> void:
	var err = ResourceLoader.load_threaded_request(path)
	if err != OK:
		_load_failed.call_deferred("Load request failed")
		return

	var status = ResourceLoader.load_threaded_get_status(path)
	while status == ResourceLoader.THREAD_LOAD_IN_PROGRESS:
		if !_is_loading || _current_path != path:
			# cancelled
			_cleanup_thread()
			return
		var progress = []
		status = ResourceLoader.load_threaded_get_status(path, progress)
		_emit_progress.call_deferred(progress[0])
		os.delay_msec(10) # Prevent tight loop

	if status == ResourceLoader.THREAD_LOAD_LOADED:
		var scene = ResourceLoader.load_threaded_get(path)
		_load_completed.call_deferred(scene)
	else:
		_load_failed.call_deferred("Load failed with status: " + str(status))

func _emit_progress(fraction):
	if _is_loading:
		progress_updated.emit(clampf(fraction, 0.0, 1.0))

func _load_completed(scene):
	if _is_loading:
		_is_loading = false
		_current_path = ""
		load_completed.emit(scene)

func _load_failed(reason):
	if _is_loading:
		_is_loading = false
		_current_path = ""
		load_failed.emit(reason)

func _cleanup_thread():
	# Nothing special needed really since Godot handles thread cleanup, but good to ensure
	pass

